        ["KIMI_API_KEY"] = new("Kimi / Moonshot", "https://platform.kimi.ai", "1. Kimi API Platform hesabına giriş yap.\n2. API Keys bölümünden anahtar oluştur.\n3. Bağlantı Merkezi → Kimi → Kaydet → Dene.\n4. Yönetim ayarları → Yapay zekâ / alternatifler → Kimi modellerini getir; hesabındaki modeli seç.\n5. Kimi alternatifini etkinleştir, alternatif sırasına Kimi ekle. Ücretsiz öncelikli açıkken Kimi kullanılmaz.\n\nAPI ücretli olabilir; sağlayıcı hesabındaki bakiye ve bütçeyi kontrol et. Web sohbetine erişim API bakiyesini doğrulamaz. Dene yalnızca model listesine erişimi kontrol eder, senaryo üretimini veya kotayı garanti etmez."),

        ["GEMINI_API_KEY"] = new("Gemini", "https://aistudio.google.com/apikey", "1. Google hesabınla Google AI Studio'ya giriş yap.\n2. API Keys → Create API key seç. Proje istenirse kendi Google Cloud projen seçilebilir; listede yoksa Import projects kullan.\n3. Oluşan anahtarı kopyala. TubeFlow → Bağlantı Merkezi → Gemini alanına yapıştır.\n4. Kaydet → Dene.\n5. Yönetim ayarları → Yapay zekâ bölümünde model ve alternatif sırasını kontrol et.\n\nGoogle TTS veya YouTube OAuth bilgilerini bu alana yazma. Ücretsiz kota hesabına ve modele bağlıdır; faturalandırmayı sağlayıcı panelinden kontrol et. HTTP 429 kota/hız sınırı, 401/403 erişim sorunudur."),

        ["NVIDIA_API_KEY"] = new("NVIDIA", "https://build.nvidia.com/", "NVIDIA hesabında API anahtarı oluştur. Otomatik model seçimi, kayıtlı NVIDIA kullanım izni açıkken modelleri kısa JSON istekleriyle arka planda sınar; kota tüketebilir. Bağlantı Merkezi → NVIDIA kartına kaydet. Yönetim ayarlarında Bulut AI ve NVIDIA iznini aç; model listesini yenile, metin modelini seç ve tüm ayarları kaydet. Dene seçili modele kısa bir istek yapar ve kota tüketebilir. Kullanım hesabının kota ve ücret koşullarına bağlıdır."),
        ["GROQ_API_KEY"] = new("Groq", "https://console.groq.com/keys", "1. Groq Console'a giriş yap veya hesap aç.\n2. API Keys → Create API Key; adını TubeFlow koy.\n3. Anahtarı kopyala → Bağlantı Merkezi → Groq → Kaydet → Dene.\n4. Yönetim ayarlarında Groq modelini ve alternatif sırasını kontrol et.\n\nHTTP 429 kota/hız sınırıdır; program diğer sağlayıcıyı deneyebilir. Model bulunamadı hatasında güncel model kimliğini sağlayıcı panelinden kontrol et. Dene yalnızca erişimi sınar; gerçek senaryo üretim kotasını garanti etmez."),

        ["OPENROUTER_API_KEY"] = new("OpenRouter", "https://openrouter.ai/settings/keys", "1. OpenRouter hesabına giriş yap.\n2. Keys → Create Key; adını TubeFlow koy.\n3. Anahtarı OpenRouter kartına yapıştır → Kaydet → Dene.\n4. Yönetim ayarlarında OpenRouter modeli openrouter/free olsun. Ücretsiz öncelikli mod açık kalsın.\n\nÜcretsiz modellerin kapasitesi sınırlıdır. Ücretsiz modda program yalnızca ücretsiz router veya :free model kimliklerini kabul eder. Anahtarın çalışması, bütün modellerin ücretsiz veya kullanılabilir olduğu anlamına gelmez."),

        ["TAVILY_API_KEY"] = new("Tavily araştırma", "https://app.tavily.com/", "1. Tavily hesabına giriş yap.\n2. Panelde API Keys bölümünden anahtar oluştur veya mevcut anahtarı kopyala.\n3. Tavily kartına yapıştır → Kaydet.\n4. İlk gerçek kontrol içerik paketindeki Araştır + yaz işleminde yapılır. Dene arama kredisi tüketmez ve canlı aramayı doğrulamaz.\n\nÜcretsiz kredi hesabına bağlıdır. Kaynak listesi oluşması, her iddianın doğrulandığı anlamına gelmez; senaryoyu ve editoryal uyarıları kontrol et. Alternatif olarak Yönetim ayarlarından konuya uygun HTTPS kaynak adresleri ekleyebilirsin."),

        ["PEXELS_API_KEY"] = new("Pexels stok video", "https://www.pexels.com/api/", "1. Pexels hesabına giriş yap → API bölümünü aç.\n2. Anahtar edinme seçeneği varsa kullanım amacını Türkçe YouTube videolarına stok görüntü eklemek olarak açıkla.\n3. Anahtarı Pexels kartına yapıştır → Kaydet → Dene.\n\n7 Ekim 2026 tarihinde yeni anahtar verilmesi durdurulmuştu. New API key issuance is currently paused yazıyorsa bu adımı geç; mevcut Pixabay bağlantısını kullan. Mevcut anahtarı olanlar erişimi test edebilir. Anahtar eksikse program kayıtlı diğer stok sağlayıcısını dener."),

        ["PIXABAY_API_KEY"] = new("Pixabay stok video", "https://pixabay.com/api/docs/", "1. Pixabay hesabına giriş yap ve API dokümantasyon sayfasını aç.\n2. Hesabına ait API key değerini bulup kopyala.\n3. Pixabay kartına yapıştır → Kaydet → Dene.\n4. Sahne editöründe kısa İngilizce aramalar yaz. Alternatifleri ; ile ayır: sunrise; morning; nature.\n\nHTTP 429 hız sınırıdır; program bekleyip tekrar dener. Aynı anahtarı kullanan başka uygulamalar da kotayı tüketebilir. Arama sonuçları 24 saat saklanır. İndirilen videolar otomatik kayıt açıkken Stok havuzuna eklenir. Uygun sonuç yoksa aramayı sadeleştir veya kendi lisanslı videonu ekle."),

        ["GOOGLE_TTS_API_KEY"] = new("Google Cloud TTS", "https://console.cloud.google.com/apis/library/texttospeech.googleapis.com", "1. Google Cloud Console'da kullanacağın projeyi seç.\n2. APIs & Services → Library → Cloud Text-to-Speech API → Enable. API Enabled veya Manage görünüyorsa etkin.\n3. APIs & Services → Credentials → Create credentials → API key.\n4. Anahtarı TubeFlow Google Cloud TTS kartına yapıştır → Kaydet → Dene.\n5. Yönetim ayarları → Ses / müzik → sağlayıcı Google Cloud TTS → Google Türkçe seslerini getir. Ses listesindeki satırdan Dinle → Kaydet.\n6. Shorts için ayrı ses seçeneği açıksa onun sağlayıcısını da kontrol et.\n\nCloud faturalandırması açık olmalıdır. Ücretsiz kota kelime değil karakter üzerinden hesaplanır ve ses ailesine bağlıdır. Yerel varsayılan sınır 900.000; diğer cihaz/programların kullanımını kapsamaz. API restrictions bölümü sunuluyorsa anahtarı Cloud Text-to-Speech API ile sınırla. YouTube Client ID/Secret veya Gemini anahtarıyla karıştırma. 403: API etkinliği, key kısıtlaması ve billing kontrolü. 429: kota/hız sınırı."),

        ["VECTEEZY_ACCOUNT_ID"] = new("Vecteezy bağlantısı", "https://www.vecteezy.com/account/developer-tools", "1. Vecteezy hesabında Developer tools bölümünü aç.\n2. Vecteezy kartındaki iki satıra Account Id ve Secret key değerlerini gir; ortak Kaydet düğmesine bas. Anahtarı sohbet veya ekran görüntüsüyle paylaşma.\n3. İki bilgi kaydedildikten sonra ortak Dene düğmesine bas: hesap arama / indirme kotası görünür, video indirilmez.\n4. Yönetim ayarları → Görüntü / altyazı: Vecteezy alternatifi ve aylık indirme sınırını kontrol et.\n\nAPI planı web Pro aboneliğinden ayrıdır. Free API planını panelde doğrula; varsayılan program sınırı 450 indirmedir. Hesap daha düşük kota verirse o sınır uygulanır. Kota dolunca başka stok kaynağı / yerel havuz denenir. Ücretsiz videoların kaynak yazısı havuzda saklanır ve YouTube açıklamasına eklenir. Ticari kullanım izinleri ve proje lisansını doğrula; Editorial içerik aranmaz."),

